#![forbid(unsafe_code)]
pub mod thermal_adapter;
use rei_microphysics::{igm_rates::{igm_rates,IgmRates,IgmRateDiagnostics},ForwardError};
use std::{cell::Cell,fs,io::{Read,Write},path::Path};
pub const N:usize=65536;
pub const SOURCE_SHA:&str="310164e620617f3089d488bd1f9668996b4a4cbd191383e45303def176ef81cf";
const MAGIC:&[u8;16]=b"AXBI_T_RATE_0001";
#[derive(Clone,Copy)] pub struct Node{pub t:f64,pub ln_t:f64,pub col:[f64;15],pub mask:u8}
pub struct Table{pub nodes:Vec<Node>,pub guards:Vec<u16>,pub lookup:Cell<u64>,pub fallback:Cell<u64>,pub direct:Cell<u64>}
pub fn temperature(j:usize)->f64{if j==0{1.0}else if j==N{1e6}else{((1e6f64).ln()*j as f64/N as f64).exp()}}
pub fn columns(r:&IgmRates)->[f64;15]{[r.ci_cm3_s[0],r.ci_cm3_s[1],r.ci_cm3_s[2],r.rr_cm3_s[0],r.rr_cm3_s[1],r.rr_cm3_s[2],r.dr_cm3_s,r.ce_erg[0],r.ce_erg[1],r.ce_erg[2],r.rr_cooling_erg_cm3_s[0],r.rr_cooling_erg_cm3_s[1],r.rr_cooling_erg_cm3_s[2],r.dr_raw_cooling_erg_cm3_s,r.freefree_erg_cm3_s]}
pub fn mask(r:&IgmRates)->u8{let mut m=0;for i in 0..3{if r.diagnostics.ci_floor_cm3_s[i]!=0.0{m|=1<<i}if r.diagnostics.ce_cap_erg[i]!=0.0{m|=1<<(i+3)}}if r.diagnostics.dr_low_branch{m|=1<<6}m}
fn invalid()->ForwardError{ForwardError::InvalidInput("IGM_TEMPERATURE_DOMAIN")}
impl Table{
 pub fn construct()->Result<Self,String>{let mut nodes=Vec::with_capacity(N+1);for j in 0..=N{let t=temperature(j);let r=igm_rates(t).map_err(|e|format!("node {j} {e:?}"))?;let col=columns(&r);if col.iter().any(|v|!v.is_finite()||(*v!=0.0&&*v<=0.0)){return Err(format!("NONPOSITIVE_NODE_COLUMN {j}"))}nodes.push(Node{t,ln_t:t.ln(),col,mask:mask(&r)});}let mut guards=vec![0u16;N];let boundaries=[5500.0,0.8*11605.0,118348.0/69.07755278982137,13179.0/69.07755278982137,473638.0/69.07755278982137,470000.0/69.07755278982137,94000.0/69.07755278982137];for j in 0..N{for (k,b) in boundaries.iter().enumerate(){if nodes[j].t<=*b&&*b<=nodes[j+1].t{guards[j]|=1<<k}}if nodes[j].mask!=nodes[j+1].mask{guards[j]|=1<<7;}}Ok(Self{nodes,guards,lookup:Cell::new(0),fallback:Cell::new(0),direct:Cell::new((N+1) as u64)})}
 pub fn save(&self,path:&Path)->Result<(),String>{let mut f=fs::File::create(path).map_err(|e|e.to_string())?;f.write_all(MAGIC).map_err(|e|e.to_string())?;f.write_all(SOURCE_SHA.as_bytes()).map_err(|e|e.to_string())?;f.write_all(&((N+1) as u32).to_le_bytes()).map_err(|e|e.to_string())?;for (j,n) in self.nodes.iter().enumerate(){for v in [n.t,n.ln_t].iter().chain(n.col.iter()){f.write_all(&v.to_bits().to_le_bytes()).map_err(|e|e.to_string())?}f.write_all(&[n.mask]).map_err(|e|e.to_string())?;if j<N{f.write_all(&self.guards[j].to_le_bytes()).map_err(|e|e.to_string())?}}Ok(())}
 pub fn load(path:&Path)->Result<Self,String>{let mut f=fs::File::open(path).map_err(|e|e.to_string())?;let mut h=[0u8;84];f.read_exact(&mut h).map_err(|e|e.to_string())?;if &h[..16]!=MAGIC||&h[16..80]!=SOURCE_SHA.as_bytes()||u32::from_le_bytes(h[80..84].try_into().unwrap())!=((N+1) as u32){return Err("TABLE_HEADER_SOURCE_OR_DIMENSION".into())}let mut nodes=Vec::with_capacity(N+1);let mut guards=Vec::with_capacity(N);for j in 0..=N{let mut v=[0f64;17];for x in &mut v{let mut b=[0u8;8];f.read_exact(&mut b).map_err(|e|e.to_string())?;*x=f64::from_bits(u64::from_le_bytes(b));}let mut mask=[0];f.read_exact(&mut mask).map_err(|e|e.to_string())?;let mut col=[0.0;15];col.copy_from_slice(&v[2..]);if v[0].to_bits()!=temperature(j).to_bits()||v[1].to_bits()!=v[0].ln().to_bits()||col.iter().any(|x|!x.is_finite()||(*x!=0.0&&*x<=0.0)){return Err(format!("TABLE_NODE_INVALID {j}"))}nodes.push(Node{t:v[0],ln_t:v[1],col,mask:mask[0]});if j<N{let mut b=[0;2];f.read_exact(&mut b).map_err(|e|e.to_string())?;guards.push(u16::from_le_bytes(b));}}let mut extra=[0];if f.read(&mut extra).map_err(|e|e.to_string())?!=0{return Err("TABLE_TRAILING_BYTES".into())}Ok(Self{nodes,guards,lookup:Cell::new(0),fallback:Cell::new(0),direct:Cell::new(0)})}
 pub fn query(&self,t:f64)->Result<IgmRates,ForwardError>{if !t.is_finite()||!(1.0..=1e6).contains(&t){return Err(invalid())}let n=self.lookup.get();if n>=8_000_000{return Err(ForwardError::InvalidInput("TABLE_LOOKUP_QUOTA"))}self.lookup.set(n+1);let j=match self.nodes.binary_search_by(|n|n.t.partial_cmp(&t).unwrap()){Ok(i)=>{if (i>0&&self.guards[i-1]!=0)||(i<N&&self.guards[i]!=0){self.fallback.set(self.fallback.get()+1);self.direct.set(self.direct.get()+1);return igm_rates(t)}return Ok(Self::assemble(self.nodes[i].col,self.nodes[i].mask,t))},Err(i)=>i-1};if self.guards[j]!=0{self.fallback.set(self.fallback.get()+1);self.direct.set(self.direct.get()+1);return igm_rates(t)}let a=&self.nodes[j];let b=&self.nodes[j+1];let u=(t.ln()-a.ln_t)/(b.ln_t-a.ln_t);let mut col=[0.0;15];for k in 0..15{col[k]=if a.col[k]==0.0&&b.col[k]==0.0{0.0}else if a.col[k]==1e-20&&b.col[k]==1e-20&&(a.mask&(1<<k))!=0{1e-20}else{((1.0-u)*a.col[k].ln()+u*b.col[k].ln()).exp()};if !col[k].is_finite()||(col[k]==0.0&&a.col[k]!=0.0)||col[k]<0.0{return Err(ForwardError::InvalidInput("TABLE_INTERPOLATION_INVALID"))}}Ok(Self::assemble(col,a.mask,t))}
 fn assemble(c:[f64;15],m:u8,t:f64)->IgmRates{let low=t/11605.0<=0.8;let floor=std::array::from_fn(|i|if m&(1<<i)!=0{c[i]}else{0.0});let cap=std::array::from_fn(|i|if m&(1<<(i+3))!=0{c[i+7]}else{0.0});IgmRates{ci_cm3_s:[c[0],c[1],c[2]],rr_cm3_s:[c[3],c[4],c[5]],dr_cm3_s:c[6],ce_erg:[c[7],c[8],c[9]],rr_cooling_erg_cm3_s:[c[10],c[11],c[12]],dr_cooling_erg_cm3_s:if low{0.0}else{c[13]},dr_raw_cooling_erg_cm3_s:c[13],freefree_erg_cm3_s:c[14],diagnostics:IgmRateDiagnostics{ci_floor_cm3_s:floor,ce_cap_erg:cap,dr_excluded_erg_cm3_s:if low{c[13]}else{0.0},dr_low_branch:low}}}
}
pub mod validation;
